                <select name="lab" class="form-control" id="test-lab" onchange="updateTestPrinters()">
                    <option value="">Select lab...</option>
                    {% for lab in labs %}
                    <option value="{{ lab }}">{{ lab }}</option>
                    {% endfor %}
                </select>
            </div>
