                <button type="button" class="btn btn-outline" onclick="testPrint()">
                    <i class="fas fa-print"></i> Test Print
                </button>
                <button type="submit" class="btn btn-primary">
                    <i class="fas fa-save"></i> Save as Draft
                </button>
            </div>
        </div>
    </div>
</form>
