{% block extra_scripts %}
<script>
    var labsDict = {{ labs_dict | safe }};

    function updateTestPrinters() {
        var labSelect = document.getElementById('test-lab');
        var printerSelect = document.getElementById('test-printer');
        var lab = labSelect.value;

        printerSelect.innerHTML = '<option value="">Select printer...</option>';
        if (lab && labsDict[lab]) {
            for (var printer in labsDict[lab]) {
                var option = document.createElement('option');
                option.value = printer;
                option.text = printer;
                printerSelect.appendChild(option);
            }
        }
    }

    async function previewTemplate() {
        var statusBadge = document.getElementById('preview-status');
        var container = document.getElementById('preview-container');
        var content = document.getElementById('zpl-editor').value;

        statusBadge.textContent = 'Loading...';
        statusBadge.className = 'badge badge-warning';

        try {
            var response = await fetch('/api/v1/preview_zpl', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ zpl_content: content })
            });
            var data = await response.json();
            if (data.png_url) {
                container.innerHTML = '<img src="' + data.png_url + '" alt="Preview" style="max-width: 100%;">';
                statusBadge.textContent = 'Ready';
                statusBadge.className = 'badge badge-success';
            } else {
                throw new Error(data.error || 'Preview failed');
            }
        } catch (err) {
            container.innerHTML = '<div class="empty-state"><i class="fas fa-exclamation-triangle"></i><p>' + err.message + '</p></div>';
            statusBadge.textContent = 'Error';
            statusBadge.className = 'badge badge-error';
        }
    }

    function testPrint() {
        var lab = document.getElementById('test-lab').value;
        var printer = document.getElementById('test-printer').value;
        if (!lab || !printer) {
            showToast('warning', 'Select Printer', 'Please select a lab and printer for test print.');
            return;
        }
        var content = document.getElementById('zpl-editor').value;
        var form = document.createElement('form');
        form.method = 'POST';
        form.action = '/api/v1/print_raw_zpl';
        form.innerHTML = '<input name="lab" value="' + lab + '"><input name="printer" value="' + printer + '"><textarea name="zpl_content">' + content + '</textarea>';
        document.body.appendChild(form);
        form.submit();
    }
</script>
{% endblock %}

def get_modern_context(request: Request, active_page: str = "", **kwargs) -> dict:
    """Build common template context for modern templates."""
    return {
        "request": request,
        "active_page": active_page,
        "local_ip": request.app.state.local_ip,
        "version": getattr(request.app.state, "version", "0.7.0"),
        "cache_bust": str(int(time.time())),
        **kwargs,
    }


def get_templates_list(pkg_path: Path) -> tuple[list, list]:
    """Get lists of stable and draft templates."""
    styles_dir = pkg_path / "etc" / "label_styles"
    stable_templates = []
    draft_templates = []

    if styles_dir.exists():
        for f in sorted(styles_dir.iterdir()):
            if f.is_file() and f.suffix == ".zpl":
                stable_templates.append(f.stem)

    tmps_dir = styles_dir / "tmps"
    if tmps_dir.exists():
        for f in sorted(tmps_dir.iterdir()):
            if f.is_file() and f.suffix == ".zpl":
                draft_templates.append(f.stem)

    return stable_templates, draft_templates


def get_stats(zp, pkg_path: Path) -> dict:
    """Calculate dashboard statistics."""
    labs = zp.printers.get("labs", {})
    total_printers = sum(len(printers) for printers in labs.values())
    stable, draft = get_templates_list(pkg_path)

    # Count backup files
    bkup_dir = pkg_path / "etc" / "old_printer_config"
    backups = len(list(bkup_dir.iterdir())) if bkup_dir.exists() else 0

    return {
        "total_labs": len(labs),
        "total_printers": total_printers,
        "online_printers": 0,  # Would need to check each printer
        "total_templates": len(stable) + len(draft),
        "backups": backups,
    }


# =============================================================================
# MODERN UI ROUTES (root level)
# =============================================================================

