{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 150 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "zebra_day/static/lsmc.css", "file_content": "/*
 * LSMC-inspired theme for Zebra Day
 * Dark, modern, clinical aesthetic with zebra stripe accents
 * Based on lsmc.com design system
 */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
    /* LSMC-inspired color palette */
    --lsmc-black: #0a0a0a;
    --lsmc-dark: #141414;
    --lsmc-gray-900: #1a1a1a;
    --lsmc-gray-800: #262626;
    --lsmc-gray-700: #333333;
    --lsmc-gray-600: #4a4a4a;
    --lsmc-gray-400: #888888;
    --lsmc-gray-300: #a3a3a3;
    --lsmc-gray-200: #d4d4d4;
    --lsmc-white: #fafafa;

    /* Zebra accent colors */
    --zebra-stripe-light: #ffffff;
    --zebra-stripe-dark: #1a1a1a;
    --zebra-accent: #6366f1;  /* Indigo accent */
    --zebra-accent-hover: #818cf8;
    --zebra-success: #22c55e;
    --zebra-warning: #f59e0b;
    --zebra-error: #ef4444;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background-color: var(--lsmc-black);
    color: var(--lsmc-white);
    padding: 24px;
    margin: 0;
    line-height: 1.6;
    font-size: 15px;
}

/* Zebra stripe decorative border at top */
body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: repeating-linear-gradient(
        90deg,
        var(--zebra-stripe-light) 0px,
        var(--zebra-stripe-light) 20px,
        var(--zebra-stripe-dark) 20px,
        var(--zebra-stripe-dark) 40px
    );
    z-index: 1000;
}

h1, h2 {
    font-family: 'Inter', sans-serif;
    font-weight: 700;
    letter-spacing: -0.02em;
    border-bottom: 1px solid var(--lsmc-gray-700);
    padding: 12px 0;
    margin-top: 32px;
    margin-bottom: 16px;
}

h1 {
    font-size: 2rem;
    color: var(--lsmc-white);
}

h2 {
    font-size: 1.25rem;
    color: var(--lsmc-gray-200);
}

small {
    display: block;
    color: var(--lsmc-gray-400);
    font-size: 0.85em;
}

a {
    color: var(--zebra-accent);
    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover {
    color: var(--zebra-accent-hover);
}

a.navigational-link {
    font-weight: 600;
    background-color: var(--zebra-accent);
    color: var(--lsmc-white);
    padding: 8px 16px;
    border-radius: 6px;
    display: inline-block;
}

a.navigational-link:hover {
    background-color: var(--zebra-accent-hover);
}

hr {
    border: 0;
    border-bottom: 1px solid var(--lsmc-gray-700);
    margin: 24px 0;
}

ul {
    list-style-type: none;
    padding-left: 0;
}

ul ul {
    padding-left: 24px;
}

li {
    padding: 4px 0;
}

/* Form inputs */
input[type=text],
input[type=email],
input[type=password],
input[type=number] {
    font-family: 'JetBrains Mono', monospace;
    padding: 12px 16px;
    border: 1px solid var(--lsmc-gray-700);
    border-radius: 6px;
    background-color: var(--lsmc-gray-900);
    color: var(--lsmc-white);
    font-size: 14px;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input[type=text]:focus,
input[type=email]:focus,
input[type=password]:focus,
input[type=number]:focus {
    border-color: var(--zebra-accent);
    outline: none;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
}

input[type=text]::placeholder {
    color: var(--lsmc-gray-600);
}

/* Submit buttons */
input[type=submit] {
    font-family: 'Inter', sans-serif;
    font-weight: 600;
    padding: 12px 24px;
    background-color: var(--zebra-accent);
    border: none;
    border-radius: 6px;
    color: var(--lsmc-white);
    cursor: pointer;
    font-size: 14px;
    transition: background-color 0.2s ease, transform 0.1s ease;
}

input[type=submit]:hover {
    background-color: var(--zebra-accent-hover);
}

input[type=submit]:active {
    transform: scale(0.98);
}

/* Regular buttons */
input[type="button"] {
    font-family: 'Inter', sans-serif;
    font-weight: 500;
    background-color: var(--lsmc-gray-800);
    border: 1px solid var(--lsmc-gray-700);
    color: var(--lsmc-white);
    padding: 12px 24px;
    font-size: 14px;
    border-radius: 6px;
    transition: all 0.2s ease;
    cursor: pointer;
}
"}

