 * Zebra Day Modern Theme
 * Ursa-inspired dark design system with zebra stripe accents
 */

/* CSS Variables */
:root {
    /* Colors - Dark theme */
    --color-primary: #1a1a2e;
    --color-secondary: #16213e;
    --color-accent: #0f3460;
    --color-highlight: #6366f1;
    --color-success: #22c55e;
    --color-warning: #f59e0b;
    --color-error: #ef4444;
    --color-info: #3b82f6;

    /* Grays */
    --color-gray-900: #0a0a0a;
    --color-gray-800: #141414;
    --color-gray-700: #1f1f1f;
    --color-gray-600: #2d2d2d;
    --color-gray-500: #4a4a4a;
    --color-gray-400: #6b6b6b;
    --color-gray-300: #a3a3a3;
    --color-gray-200: #d4d4d4;
    --color-gray-100: #f5f5f5;
    --color-white: #fafafa;
    --color-dark: #0a0a0a;

    /* Typography */
    --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --font-mono: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;

    /* Spacing */
    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;

    /* Border Radius */
    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 12px;
    --radius-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.3);
    --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.4);

    /* Transitions */
    --transition-fast: 0.15s ease;
    --transition-normal: 0.3s ease;
}

/* Reset & Base */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 16px;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-primary);
    background-color: var(--color-gray-900);
    color: var(--color-gray-200);
    line-height: 1.6;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

