                    <input type="text" name="alt_a" class="form-control" placeholder="Field A">
                </div>
                <div class="form-group">
                    <label class="form-label">Alt B</label>
                    <input type="text" name="alt_b" class="form-control" placeholder="Field B">
                </div>
                <div class="form-group">
