{% block title %}Edit: {{ filename }} - Zebra Day{% endblock %}

{% block extra_head %}
<style>
    .editor-container { display: grid; grid-template-columns: 1fr 1fr; gap: var(--spacing-lg); }
    .editor-textarea { min-height: 500px; font-family: var(--font-mono); font-size: 14px; }
